{"code":"import pandas as pd, numpy as np, statsmodels.formula.api as smf
D=pd.read_csv('data/explore.csv')
xs=['nitrogen_ppm','phosphorus_ppm','potassium_ppm','soil_ph','irrigation_mm','seed_density','mulch_depth_cm','biochar_g','fungicide_ml','shade_pct']
for x in xs:
 d=D[['yield_kg',x,'farm']].dropna(); m=smf.ols(f'yield_kg ~ {x} + C(farm)',d).fit()
 print(x,len(d),round(m.params[x],4),round(m.pvalues[x],5),round(m.rsquared,4))"}
